; Planar line plotter into the WRAM framebuffer: bitplane 0 (colour 1), or bitplane 1 (colour 2)
; when hPlane = 1.
; Bodies are generated by tools/gbc_genlines.py.

INCLUDE "hw.inc"

; HL += FB_STRIDE (next framebuffer column). A (the error term) is preserved via E.
MACRO COLSTEP
    ld e, a
    ld a, l
    add FB_STRIDE
    ld l, a
    jr nc, .nc\@
    inc h
.nc\@:
    ld a, e
ENDM

; Base address of each framebuffer column (16 entries, 32-byte aligned).
SECTION "colbase", ROM0, ALIGN[5]
ColBase::
FOR i, VIEW_COLS
    dw FB + i * FB_STRIDE
ENDR

SECTION "line", ROM0

; B=x0 C=y0 D=x1 E=y1, all within the viewport (0..127, 0..111). Clobbers all.
DrawLine::
    ld a, d
    cp b
    jr nc, .ordered
    ld a, b
    ld b, d
    ld d, a
    ld a, c
    ld c, e
    ld e, a
.ordered:
    ld a, b
    and 7
    ldh [hPhase], a
    ld a, b
    srl a
    srl a
    srl a
    add a                           ; column * 2
    add LOW(ColBase)
    ld l, a
    ld h, HIGH(ColBase)
    ld a, [hl+]
    ld h, [hl]
    ld l, a                         ; HL = column base
    ld a, c
    add a                           ; y * 2
    add l
    ld l, a
    ld a, h
    adc 0
    ld h, a
    ldh a, [hPlane]                 ; 0: bitplane 0 (ink), 1: bitplane 1 (red); rows are even
    or l
    ld l, a
    ldh [hPtrL], a
    ld a, h
    ldh [hPtrH], a
    ld a, d
    sub b
    ld d, a                         ; D = dx
    ld a, e
    sub c                           ; y1 - y0
    jr nc, .down
    cpl
    inc a
    ld e, a                         ; E = dy
    ld a, 1                         ; up
    jr .haveDir
.down:
    ld e, a
    xor a
.haveDir:
    ldh [hKind], a
    ld a, d
    cp e
    jr c, .ymajor
    ld b, d                         ; B = M = dx
    ld c, e                         ; C = m = dy
    ldh a, [hKind]
    jr .haveKind
.ymajor:
    ld b, e                         ; B = M = dy
    ld c, d                         ; C = m = dx
    ldh a, [hKind]
    add 2
.haveKind:
    swap a                          ; kind * 16
    ld e, a
    ldh a, [hPhase]
    add a
    add e
    ld e, a
    ld d, 0
    ld hl, LineTable
    add hl, de
    ld a, [hl+]
    ld h, [hl]
    ld l, a
    push hl                         ; body entry; the `ret` below jumps to it
    ld a, b
    inc a
    ld d, a                         ; D = pixel count
    ldh a, [hPtrH]
    ld h, a
    ldh a, [hPtrL]
    ld l, a
    ld a, b
    srl a                           ; A = M / 2
    ret

INCLUDE "line_bodies.inc"
